# ============================================================
# REFERENCE WINDOWS
# ============================================================

def envelope_levels(audio, window_seconds=0.25, hop_seconds=0.125):
    mono = to_mono(audio)
    window = max(1, int(round(window_seconds * SR)))
    hop = max(1, int(round(hop_seconds * SR)))
    starts, values = [], []
    for start in range(0, max(1, len(mono) - window + 1), hop):
        chunk = mono[start:start + window]
        value = np.sqrt(np.mean(chunk * chunk) + 1e-12)
        starts.append(start)
        values.append(20 * np.log10(value + 1e-9))
    return np.asarray(starts, dtype=np.int64), np.asarray(values, dtype=np.float32)


def window_stability(audio):
    _, levels = envelope_levels(audio)
    if len(levels) < 3:
        return {"score": 999.0, "valley": 99.0}
    median = float(np.median(levels))
    p10 = float(np.percentile(levels, 10))
    valley = median - p10
    dropout = float(np.mean(levels < (median - 10)))
    spread = float(np.percentile(levels, 95) - np.percentile(levels, 5))
    score = valley * 3.0 + dropout * 100.0 + max(0, spread - 24) * 1.5
    return {"score": float(score), "valley": float(valley), "dropout": dropout, "spread": spread}


def repair_reference(audio):
    audio = f32(audio)
    starts, levels = envelope_levels(audio, 0.10, 0.05)
    if len(levels) < 3:
        return audio
    median = float(np.median(levels))
    correction = np.minimum(np.maximum((median - 7.0) - levels, 0.0), 8.0)
    kernel = np.ones(12, dtype=np.float32) / np.float32(12)  # ~600 ms
    correction = np.convolve(correction, kernel, mode="same")
    correction_db = np.interp(np.arange(len(audio), dtype=np.float64), starts, correction)
    gain = (10 ** (correction_db / 20)).astype(np.float32)
    return normalize_peak(audio * gain[:, None], 0.85)


def choose_references(motif):
    reference_samples = int(round(PHRASE_DURATION * SR))
    step = int(round(0.50 * SR))
    candidates = []
    for start in range(0, max(1, len(motif) - reference_samples + 1), step):
        window = motif[start:start + reference_samples]
        if len(window) < reference_samples:
            continue
        candidates.append((window_stability(window)["score"], start))
    if not candidates:
        candidates = [(0.0, 0)]
    candidates.sort(key=lambda x: x[0])

    selected = []
    min_distance = int(round(2.0 * SR))
    for _, start in candidates:
        if all(abs(start - previous) >= min_distance for previous in selected):
            selected.append(start)
        if len(selected) == 4:
            break
    while len(selected) < 4:
        selected.append(candidates[len(selected) % len(candidates)][1])

    references = [
        f32(repair_reference(fit_length(motif[s:s + reference_samples], reference_samples)))
        for s in selected
    ]
    return references, selected


# ============================================================
# CHROMA + PHRASE QUALITY GATES
# ============================================================

def chroma_profile(audio):
    try:
        import librosa
    except Exception:
        return None
    mono = to_mono(audio)
    if len(mono) < SR * 2:
        mono = np.pad(mono, (0, int(SR * 2) - len(mono)))
    chroma = librosa.feature.chroma_stft(y=mono, sr=SR, n_fft=4096, hop_length=1024)
    profile = f32(chroma.mean(axis=1))
    profile /= np.linalg.norm(profile) + 1e-9
    return profile


def phrase_quality(audio, motif_profile):
    audio = f32(audio)
    _, levels = envelope_levels(audio)
    if len(levels) < 4:
        return {"valid": False, "quality": -999.0, "failures": ["too_short"], "motif_similarity": None}

    median = float(np.median(levels))
    p05 = float(np.percentile(levels, 5))
    local_valley = median - p05
    bad = levels < (median - 10)
    bad_fraction = float(np.mean(bad))

    longest = current = 0
    for value in bad:
        current = current + 1 if value else 0
        longest = max(longest, current)
    longest_seconds = longest * 0.125

    spread = float(np.percentile(levels, 95) - np.percentile(levels, 5))
    edge = int(round(0.75 * SR))
    mono = to_mono(audio)
    head_drop = median - rms_db(mono[:edge])
    tail_drop = median - rms_db(mono[-edge:])

    similarity = None
    if motif_profile is not None:
        candidate_profile = chroma_profile(audio)
        if candidate_profile is not None:
            similarity = float(np.dot(motif_profile, candidate_profile))

    failures = []
    if local_valley > 11.0:
        failures.append("deep_local_valley")
    if bad_fraction > 0.08:
        failures.append("dropout_fraction")
    if longest_seconds > 0.75:
        failures.append("long_valley")
    if head_drop > 12.0:
        failures.append("head_collapse")
    if tail_drop > 12.0:
        failures.append("tail_collapse")
    if spread > 28.0:
        failures.append("level_swing")
    if similarity is not None and similarity < 0.88:
        failures.append("weak_motif")

    quality = 100.0
    quality -= local_valley * 2.5
    quality -= bad_fraction * 160.0
    quality -= max(0.0, longest_seconds - 0.25) * 20.0
    quality -= max(0.0, spread - 20.0) * 1.2
    if similarity is not None:
        quality += (similarity - 0.90) * 70.0

    return {
        "valid": len(failures) == 0,
        "quality": float(quality),
        "local_valley_db": float(local_valley),
        "dropout_fraction": bad_fraction,
        "longest_valley_seconds": float(longest_seconds),
        "head_drop_db": float(head_drop),
        "tail_drop_db": float(tail_drop),
        "level_spread_db": spread,
        "motif_similarity": similarity,
        "failures": failures,
    }


# ============================================================
# LAYER PHRASES
# ============================================================

def layer_prompts(mood):
    return {
        "core": (
            f"cinematic {mood} story "
            "underscore, "
            "same memorable three-note "
            "descending motif, "
            "felt piano, "
            "warm restrained bass, "
            "dark soft pad, "
            "sparse continuous musical bed, "
            "no silence, no pauses, "
            "instrumental only, no vocals"
        ),
        "pressure": (
            f"cinematic {mood} thriller "
            "pressure layer, "
            "same three-note descending "
            "felt piano motif, "
            "deeper bass pulse, "
            "subtle rhythmic movement, "
            "dark pad, "
            "increasing suspense, "
            "continuous musical bed, "
            "no silence, "
            "instrumental only, no vocals"
        ),
        "climax": (
            f"cinematic {mood} revelation "
            "climax layer, "
            "same three-note descending motif, "
            "wider piano register, "
            "deep bass pulse, "
            "controlled dramatic percussion, "
            "serious revelation, "
            "powerful but restrained, "
            "continuous musical bed, "
            "no silence, "
            "instrumental only, no vocals"
        ),
    }


def _fmt_similarity(value):
    return "n/a" if value is None else f"{value:.3f}"


def generate_layer_phrases(story_index, mood, references, motif_profile, story_dir, run_seed, log=print):
    prompts = layer_prompts(mood)
    phrase_samples = int(round(PHRASE_DURATION * SR))
    layer_phrases = {name: [] for name in LAYER_NAMES}
    quality_rows = []
    provider = get_provider()

    for layer in LAYER_NAMES:
        log(f"\nGenerating {layer}...")
        for phrase_index in range(PHRASES_PER_LAYER):
            best_audio, best_report, accepted = None, None, False
            ref_index = (phrase_index + LAYER_REFERENCE_OFFSET[layer]) % len(references)
            reference = references[ref_index]

            for attempt in range(MAX_ATTEMPTS):
                seed = derive_seed(run_seed, "layer", layer, story_index, phrase_index, attempt)
                log(f"  phrase {phrase_index + 1}/{PHRASES_PER_LAYER} "
                    f"attempt {attempt + 1}/{MAX_ATTEMPTS} ref={ref_index + 1}")
                try:
                    generated = provider.generate_conditioned(prompts[layer], PHRASE_DURATION, reference,
                                                               LAYER_NOISE[layer], seed)
                    generated = normalize_peak(fit_length(generated, phrase_samples), 0.85)
                    report = phrase_quality(generated, motif_profile)
                    quality_rows.append({"layer": layer, "phrase": phrase_index + 1,
                                         "attempt": attempt + 1, "seed": seed,
                                         "reference": ref_index + 1, **report})
                    log(f"    quality={report['quality']:.1f} "
                        f"valley={report.get('local_valley_db', float('nan')):.1f}dB "
                        f"motif={_fmt_similarity(report.get('motif_similarity'))}")
                    if best_report is None or report["quality"] > best_report["quality"]:
                        best_audio, best_report = generated, report
                    if report["valid"]:
                        accepted = True
                        break
                except Exception as exc:
                    log(f"    generation error: {exc!r}")

            if best_audio is None:
                raise RuntimeError(f"No candidate for {layer} phrase {phrase_index + 1}")
            if not accepted:
                log("    fallback to best candidate")

            write_audio(story_dir / f"{layer}_phrase_{phrase_index + 1:02d}.wav", best_audio, SR)
            layer_phrases[layer].append(best_audio)

    return layer_phrases, quality_rows

# ##########  mix_engineering.py  ##########

# ============================================================
# STORY SCORING LAB — MIX / MASTER ENGINEERING STAGE
#
# Everything a mix/mastering engineer would check or do between "the score
# is rendered" and "the file ships", in pure numpy + scipy.signal:
#
#   Metering (standards-based, not ad-hoc RMS):
#     - ITU-R BS.1770-4 K-weighted loudness: integrated (gated), momentary
#       (400 ms), short-term (3 s)
#     - EBU Tech 3342 loudness range (LRA)
#     - ITU-R BS.1770-4 Annex 2 true peak (4x oversampled, dBTP)
#     - PLR, crest factor, clipping runs, DC offset, noise floor
#     - stereo phase correlation, mid/side width, mono fold-down loss
#     - octave-band spectral balance
#     - dialogue masking margin (voice vs music in the 1-4 kHz speech band)
#
#   Processing (the dialogue mix + master bus):
#     - subsonic high-pass on music, rumble high-pass on voice
#     - dialogue-to-music-ratio ducking with lookahead (the music moves
#       BEFORE the line starts, the way a mixer rides the fader), hold
#       between words so it doesn't pump
#     - speech-band "carve": a dynamic presence dip in the music only while
#       the narrator is talking, so less broadband ducking is needed
#     - loudness normalization to a delivery spec + true-peak lookahead
#       limiter at the spec's ceiling
#
# This module is ADDITIVE. scoring_engine.render_score()/measure_score()
# (the validated optimizer path) and the legacy score_ducked /
# voice_music_preview outputs are untouched.
# ============================================================

import math
from dataclasses import dataclass, asdict

import numpy as np
from scipy.ndimage import maximum_filter1d, minimum_filter1d, uniform_filter1d
from scipy.signal import butter, lfilter, resample_poly, sosfilt, welch


# ============================================================
# DELIVERY SPECS
# ============================================================

@dataclass(frozen=True)
class DeliverySpec:
    name: str
    integrated_lufs: float
    true_peak_dbtp: float
    tolerance_lu: float = 1.0


DELIVERY_SPECS = {
    # YouTube / Shorts / TikTok / Reels / Spotify normalise to ~-14 LUFS.
    "shorts": DeliverySpec("shorts", -14.0, -1.0),
    # Apple Podcasts / AES TD1004 spoken-word guidance.
    "podcast": DeliverySpec("podcast", -16.0, -1.0),
    # EBU R128 broadcast.
    "ebu_r128": DeliverySpec("ebu_r128", -23.0, -1.0, 0.5),
    # ATSC A/85 (US broadcast).
    "atsc_a85": DeliverySpec("atsc_a85", -24.0, -2.0, 2.0),
}
DEFAULT_DELIVERY = "shorts"


@dataclass(frozen=True)
class MixSettings:
    # Dialogue-to-music ratio while the narrator speaks: speech-gated voice
    # loudness minus the music bed's short-term loudness. 12-18 LU is the
    # usual range for narration over score; 15 keeps the score present.
    target_dmr_lu: float = 15.0
    max_duck_db: float = 12.0
    duck_lookahead_s: float = 0.20     # music starts dipping before the line
    duck_attack_s: float = 0.12
    duck_hold_s: float = 0.35          # bridges inter-word gaps (no pumping)
    duck_release_s: float = 0.90
    # Presence carve on the music under speech (dynamic peaking cut).
    carve_center_hz: float = 2500.0
    carve_q: float = 0.9
    carve_depth_db: float = 4.0
    # Filtering.
    music_highpass_hz: float = 30.0
    voice_highpass_hz: float = 70.0
    # Limiter.
    limiter_window_s: float = 0.015    # +-15 ms lookahead, ~30 ms ramps


# QC thresholds. Each one is a widely used engineering rule of thumb,
# not a law; they produce warnings in the report, never hard failures.
QC = {
    "clip_run_samples": 3,           # 3+ consecutive full-scale samples = clip
    "clip_level": 0.999,
    "dc_offset_max": 0.001,           # ~ -60 dBFS
    "min_plr_db": 8.0,                # below this the master is crushed
    "min_correlation": -0.2,          # 5th-pct window below this = phase problem
    "max_mono_loss_lu": 3.0,
    "min_masking_margin_db": 6.0,     # voice over music in the speech band
    "max_sub_share_db": -12.0,        # <40 Hz energy vs full band
    "max_lra_lu_narration": 15.0,
}

SPEECH_BAND = (1000.0, 4000.0)
OCTAVE_CENTERS = (31.5, 63, 125, 250, 500, 1000, 2000, 4000, 8000, 16000)

ABSOLUTE_GATE_LUFS = -70.0
SILENCE_LUFS = -120.0


# ============================================================
# SMALL HELPERS
# ============================================================

def _f64(audio):
    audio = np.asarray(audio, dtype=np.float64)
    return audio[:, None] if audio.ndim == 1 else audio


def _db(power):
    return 10.0 * np.log10(np.maximum(power, 1e-12))   # floor -120 dB


def _lufs_from_power(power):
    # BS.1770: L = -0.691 + 10 log10(sum_c G_c * z_c); G = 1 for L/R/C.
    power = np.asarray(power, dtype=np.float64)
    return np.where(power > 0, -0.691 + _db(power), SILENCE_LUFS)


def as_stereo(audio):
    audio = _f64(audio)
    if audio.shape[1] == 1:
        return np.repeat(audio, 2, axis=1)
    return audio[:, :2]


# ============================================================
# K-WEIGHTING (BS.1770-4) — coefficients derived for any sample rate
# ============================================================

def k_weighting_coeffs(sr):
    """Two biquads: high-shelf ('head' pre-filter) and RLB high-pass. At 48 kHz
    these reproduce the coefficient tables printed in BS.1770-4."""
    # Stage 1: high shelf.
    f0, gain_db, q = 1681.974450955533, 3.999843853973347, 0.7071752369554196
    k = math.tan(math.pi * f0 / sr)
    vh = 10.0 ** (gain_db / 20.0)
    vb = vh ** 0.4996667741545416
    a0 = 1.0 + k / q + k * k
    b1 = np.array([(vh + vb * k / q + k * k) / a0,
                   2.0 * (k * k - vh) / a0,
                   (vh - vb * k / q + k * k) / a0])
    a1 = np.array([1.0, 2.0 * (k * k - 1.0) / a0, (1.0 - k / q + k * k) / a0])
    # Stage 2: RLB high-pass.
    f0, q = 38.13547087602444, 0.5003270373238773
    k = math.tan(math.pi * f0 / sr)
    a0 = 1.0 + k / q + k * k
    b2 = np.array([1.0, -2.0, 1.0])
    a2 = np.array([1.0, 2.0 * (k * k - 1.0) / a0, (1.0 - k / q + k * k) / a0])
    return (b1, a1), (b2, a2)


def k_weight(audio, sr):
    audio = _f64(audio)
    (b1, a1), (b2, a2) = k_weighting_coeffs(sr)
    return lfilter(b2, a2, lfilter(b1, a1, audio, axis=0), axis=0)


def _block_power(weighted, sr, window_s, hop_s):
    """Mean-square per channel over sliding windows, summed over channels."""
    n = weighted.shape[0]
    win = int(round(window_s * sr))
    hop = int(round(hop_s * sr))
    summed = np.sum(weighted * weighted, axis=1)
    if n < win:
        return np.array([summed.mean() if n else 0.0]), np.array([0])
    csum = np.concatenate([[0.0], np.cumsum(summed)])
    starts = np.arange(0, n - win + 1, hop)
    return (csum[starts + win] - csum[starts]) / win, starts


def _gated_integrated(block_power):
    """Two-stage gate of BS.1770-4 applied to a set of block powers."""
    block_power = np.asarray(block_power, dtype=np.float64)
    loud = _lufs_from_power(block_power)
    stage1 = block_power[loud > ABSOLUTE_GATE_LUFS]
    if stage1.size == 0:
        return SILENCE_LUFS
    relative_gate = float(_lufs_from_power(stage1.mean())) - 10.0
    stage2 = block_power[(loud > ABSOLUTE_GATE_LUFS) & (loud > relative_gate)]
    if stage2.size == 0:
        return SILENCE_LUFS
    return float(_lufs_from_power(stage2.mean()))


def integrated_loudness(audio, sr, weighted=None):
    """Gated integrated loudness, LUFS (400 ms blocks, 75 % overlap)."""
    weighted = k_weight(audio, sr) if weighted is None else weighted
    power, _ = _block_power(weighted, sr, 0.4, 0.1)
    return _gated_integrated(power)


def loudness_curve(audio, sr, window_s, hop_s=0.1, weighted=None):
    """(times_s, LUFS) — window 0.4 = momentary, 3.0 = short-term."""
    weighted = k_weight(audio, sr) if weighted is None else weighted
    power, starts = _block_power(weighted, sr, window_s, hop_s)
    centers = (starts + int(round(window_s * sr)) / 2.0) / sr
    return centers, _lufs_from_power(power)


def loudness_range(audio, sr, weighted=None):
    """EBU Tech 3342 LRA: P95 - P10 of gated short-term loudness."""
    weighted = k_weight(audio, sr) if weighted is None else weighted
    power, _ = _block_power(weighted, sr, 3.0, 0.1)
    loud = _lufs_from_power(power)
    gated = power[loud > ABSOLUTE_GATE_LUFS]
    if gated.size < 2:
        return 0.0
    rel = float(_lufs_from_power(gated.mean())) - 20.0
    values = _lufs_from_power(gated)
    values = values[values > rel]
    if values.size < 2:
        return 0.0
    return float(np.percentile(values, 95) - np.percentile(values, 10))


# ============================================================
# TRUE PEAK (BS.1770-4 Annex 2)
# ============================================================

def true_peak_envelope(audio, sr, block=1 << 18, pad=64):
    """Per-sample inter-sample peak magnitude (max over all channels and the
    oversampled points belonging to each input sample). Processed in padded
    blocks so a 90 s file doesn't need a 4x float64 copy in memory."""
    audio = _f64(audio)
    factor = 4 if sr < 96000 else (2 if sr < 192000 else 1)
    n = audio.shape[0]
    if factor == 1 or n == 0:
        return np.max(np.abs(audio), axis=1) if n else np.zeros(0)
    out = np.empty(n)
    for start in range(0, n, block):
        stop = min(n, start + block)
        lo, hi = max(0, start - pad), min(n, stop + pad)
        up = resample_poly(audio[lo:hi], factor, 1, axis=0)
        up = np.abs(up[(start - lo) * factor:(stop - lo) * factor]).max(axis=1)
        out[start:stop] = up.reshape(-1, factor).max(axis=1)
    return out


def true_peak_dbtp(audio, sr):
    peak = float(np.max(true_peak_envelope(audio, sr))) if len(audio) else 0.0
    return 20.0 * math.log10(max(peak, 1e-12))


# ============================================================
# FILTERS
# ============================================================

def highpass(audio, sr, hz, order=2):
    sos = butter(order, hz, btype="highpass", fs=sr, output="sos")
    return sosfilt(sos, _f64(audio), axis=0)


def _bandpass_rbj(sr, f0, q):
    """RBJ constant 0 dB peak-gain band-pass."""
    w0 = 2.0 * math.pi * f0 / sr
    alpha = math.sin(w0) / (2.0 * q)
    a0 = 1.0 + alpha
    b = np.array([alpha, 0.0, -alpha]) / a0
    a = np.array([1.0, -2.0 * math.cos(w0) / a0, (1.0 - alpha) / a0])
    return b, a


def dynamic_presence_cut(audio, sr, gain_db_curve, f0, q):
    """Time-varying peaking EQ: y = x + (A(t) - 1) * BP(x). With A=1 the
    signal is untouched; with A<1 it dips around f0 by exactly 20log10(A)."""
    audio = _f64(audio)
    b, a = _bandpass_rbj(sr, f0, q)
    band = lfilter(b, a, audio, axis=0)
    amount = 10.0 ** (np.asarray(gain_db_curve, dtype=np.float64) / 20.0) - 1.0
    return audio + band * amount[:, None]


# ============================================================
# SPEECH ACTIVITY
# ============================================================

def speech_activity(voice_mono, sr, frame_s=0.02, hangover_s=0.25):
    """Boolean speech mask per frame + frame times. Threshold adapts to the
    recording: 12 dB over the noise floor, but never more than 30 dB under
    the loud speech level."""
    voice = highpass(np.asarray(voice_mono, dtype=np.float64), sr, 100.0)[:, 0]
    frame = int(round(frame_s * sr))
    n_frames = max(1, len(voice) // frame)
    power = np.mean(voice[: n_frames * frame].reshape(n_frames, frame) ** 2, axis=1)
    level = _db(power)
    floor = np.percentile(level, 10)
    loud = np.percentile(level, 95)
    threshold = min(floor + 12.0, loud - 6.0)
    threshold = max(threshold, loud - 30.0)
    active = level > threshold
    hang = max(1, int(round(hangover_s / frame_s)))
    active = maximum_filter1d(active.astype(np.uint8), size=2 * hang + 1) > 0
    times = (np.arange(n_frames) + 0.5) * frame / sr
    return active, times, {"threshold_db": float(threshold), "floor_db": float(floor),
                            "speech_p95_db": float(loud)}


# ============================================================
# DIALOGUE DUCKING (target DMR, lookahead, hold, asymmetric smoothing)
# ============================================================

def _smooth_asymmetric(target_db, frame_s, attack_s, release_s):
    """One-pole smoothing at frame rate: fast into gain reduction, slow out."""
    att = math.exp(-frame_s / max(attack_s, 1e-6))
    rel = math.exp(-frame_s / max(release_s, 1e-6))
    out = np.empty_like(target_db)
    current = 0.0
    for i, value in enumerate(target_db):
        coeff = att if value < current else rel
        current = coeff * current + (1.0 - coeff) * value
        out[i] = current
    return out


def _lookahead_min(values, look):
    """out[t] = min(values[t .. t+look])."""
    if look <= 0:
        return values
    padded = np.concatenate([values, np.full(look, values[-1])])
    return np.lib.stride_tricks.sliding_window_view(padded, look + 1).min(axis=1)


def dialogue_duck_curve(voice_mono, music, sr, settings=MixSettings()):
    """Per-sample gain (dB, <= 0) for the music bed, plus the per-sample
    speech-activity weight (0..1) used to drive the presence carve."""
    n = len(music)
    frame_s = 0.02
    active, times, vad = speech_activity(voice_mono, sr, frame_s)

    voice_w = k_weight(as_stereo(voice_mono), sr)   # as it sits in the mix
    voice_power, _ = _block_power(voice_w, sr, 0.4, 0.1)
    # Speech-gated narration loudness: the dialogue anchor of the mix.
    voice_lufs = _gated_integrated(voice_power)

    # Music short-term loudness (3 s) — slow enough that ducking follows
    # the score's arc, not its individual notes.
    m_times, m_lufs = loudness_curve(music, sr, 3.0, 0.1)
    music_st = np.interp(times, m_times, m_lufs)

    needed = settings.target_dmr_lu - (voice_lufs - music_st)
    target = -np.clip(needed, 0.0, settings.max_duck_db) * active

    # Hold the deepest duck across short gaps (no pumping between words),
    # then look ahead so the music is already moving when the line starts.
    hold = max(1, int(round(settings.duck_hold_s / frame_s)))
    look = int(round(settings.duck_lookahead_s / frame_s))
    target = _lookahead_min(minimum_filter1d(target, size=hold, mode="nearest"), look)
    smooth = _smooth_asymmetric(target, frame_s, settings.duck_attack_s, settings.duck_release_s)

    speaking = _lookahead_min(-active.astype(np.float64), look)
    activity = _smooth_asymmetric(speaking, frame_s, settings.duck_attack_s, settings.duck_release_s)
    sample_t = np.arange(n) / sr
    duck_db = np.interp(sample_t, times, smooth)
    weight = -np.interp(sample_t, times, activity)
    stats = {
        "voice_speech_lufs": float(voice_lufs),
        "speech_fraction": float(np.mean(active)),
        "average_duck_db_during_speech": float(np.mean(smooth[active])) if active.any() else 0.0,
        "max_duck_db": float(np.min(smooth)),
        "vad": vad,
    }
    return duck_db, weight, stats


# ============================================================
# LIMITER (true-peak aware, lookahead, zero overshoot by construction)
# ============================================================

def true_peak_limit(audio, sr, ceiling_dbtp, window_s=0.015):
    """Lookahead brick-wall limiter driven by the true-peak envelope.

    gain = moving_average_{+-w}( min_{+-w}(required) ). Every value in the
    average window around a peak is a minimum over a window that contains
    that peak, so gain <= required there: the ceiling holds by construction,
    with smooth ~2w ramps in and out (no per-sample gain ripple, which is
    what makes cheap limiters distort bass)."""
    audio = _f64(audio)
    ceiling = 10.0 ** (ceiling_dbtp / 20.0)
    required = np.minimum(1.0, ceiling / np.maximum(true_peak_envelope(audio, sr), 1e-12))
    if required.min() >= 1.0:
        return audio.copy(), 0.0
    size = 2 * max(1, int(round(window_s * sr))) + 1
    gain = minimum_filter1d(required, size=size, mode="nearest")
    gain = uniform_filter1d(gain, size=size, mode="nearest")
    out = audio * gain[:, None]
    # Resampler ringing can leave a few hundredths of a dB; trim it.
    over = true_peak_dbtp(out, sr) - ceiling_dbtp
    if over > 0:
        out *= 10.0 ** (-(over + 0.01) / 20.0)
    return out, float(-20.0 * np.log10(max(gain.min(), 1e-12)))


def master_to_spec(audio, sr, spec, settings=MixSettings()):
    """Loudness-normalise to spec.integrated_lufs, then true-peak limit.
    Two passes because limiting lowers integrated loudness slightly."""
    audio = _f64(audio)
    max_gr = 0.0
    out = audio
    for _ in range(3):
        current = integrated_loudness(out, sr)
        if current <= SILENCE_LUFS:
            break
        gain_db = spec.integrated_lufs - current
        out = out * 10.0 ** (gain_db / 20.0)
        out, gr = true_peak_limit(out, sr, spec.true_peak_dbtp, settings.limiter_window_s)
        max_gr = max(max_gr, gr)
        if abs(integrated_loudness(out, sr) - spec.integrated_lufs) < 0.1:
            break
    return out, max_gr


# ============================================================
# QC REPORT
# ============================================================

def _clip_runs(audio, level, run):
    hot = np.any(np.abs(audio) >= level, axis=1).astype(np.int8)
    if not hot.any():
        return 0
    edges = np.diff(np.concatenate([[0], hot, [0]]))
    starts = np.flatnonzero(edges == 1)
    ends = np.flatnonzero(edges == -1)
    return int(np.sum((ends - starts) >= run))


def _correlation(audio, sr, window_s=0.4):
    left, right = audio[:, 0], audio[:, 1]
    win = int(round(window_s * sr))
    n = (len(left) // win) * win
    if n == 0:
        return 1.0, 1.0
    l = left[:n].reshape(-1, win)
    r = right[:n].reshape(-1, win)
    num = np.sum(l * r, axis=1)
    den = np.sqrt(np.sum(l * l, axis=1) * np.sum(r * r, axis=1))
    valid = den > 1e-9
    if not valid.any():
        return 1.0, 1.0
    corr = num[valid] / den[valid]
    return float(np.mean(corr)), float(np.percentile(corr, 5))


def octave_balance(audio, sr):
    """Octave-band energy relative to total (dB) from a Welch LTAS."""
    mono = _f64(audio).mean(axis=1)
    freqs, psd = welch(mono, fs=sr, nperseg=8192)
    total = np.sum(psd) + 1e-30
    bands = {}
    for fc in OCTAVE_CENTERS:
        lo, hi = fc / math.sqrt(2), fc * math.sqrt(2)
        sel = (freqs >= lo) & (freqs < min(hi, sr / 2))
        bands[f"{fc:g}Hz"] = float(_db(np.sum(psd[sel]) / total)) if sel.any() else None
    sub = float(_db(np.sum(psd[freqs < 40.0]) / total))
    # Tilt: slope of octave-band energy 125 Hz - 8 kHz, dB per octave.
    xs = [math.log2(fc) for fc in OCTAVE_CENTERS[2:9]]
    ys = [bands[f"{fc:g}Hz"] for fc in OCTAVE_CENTERS[2:9]]
    tilt = float(np.polyfit(xs, ys, 1)[0]) if all(y is not None for y in ys) else None
    return bands, sub, tilt


def masking_margin(voice_mono, music, sr, active_mask, mask_times):
    """Median voice-minus-music level in the 1-4 kHz speech band over
    speech frames. Below ~6 dB, consonants start getting lost."""
    sos = butter(4, SPEECH_BAND, btype="bandpass", fs=sr, output="sos")
    v = sosfilt(sos, _f64(voice_mono), axis=0).mean(axis=1)
    m = sosfilt(sos, _f64(music), axis=0).mean(axis=1)
    frame = int(round((mask_times[1] - mask_times[0]) * sr)) if len(mask_times) > 1 else len(v)
    n = min(len(active_mask), len(v) // frame)
    if n == 0 or not active_mask[:n].any():
        return None
    vp = np.mean(v[: n * frame].reshape(n, frame) ** 2, axis=1)
    mp = np.mean(m[: n * frame].reshape(n, frame) ** 2, axis=1)
    sel = active_mask[:n] & (vp > 0)
    # Integrate over 200 ms so single plosive frames don't dominate.
    vp = uniform_filter1d(vp, 10)
    mp = uniform_filter1d(mp, 10)
    return float(np.median(_db(vp[sel]) - _db(mp[sel])))


def qc_report(audio, sr, spec=None, voice_mono=None, music=None, label=""):
    """Engineering QC for one rendered file. Returns metrics + warnings."""
    stereo = as_stereo(audio)
    weighted = k_weight(stereo, sr)
    integrated = integrated_loudness(stereo, sr, weighted)
    _, short_term = loudness_curve(stereo, sr, 3.0, 0.1, weighted)
    _, momentary = loudness_curve(stereo, sr, 0.4, 0.1, weighted)
    tp = true_peak_dbtp(stereo, sr)
    sample_peak = 20.0 * math.log10(max(float(np.max(np.abs(stereo))), 1e-12))
    rms = 10.0 * math.log10(max(float(np.mean(stereo ** 2)), 1e-30))
    mono_fold = stereo.mean(axis=1, keepdims=True)
    mono_lufs = integrated_loudness(np.repeat(mono_fold, 2, axis=1), sr)
    corr_mean, corr_p5 = _correlation(stereo, sr)
    mid = stereo.mean(axis=1)
    side = (stereo[:, 0] - stereo[:, 1]) * 0.5
    width_db = float(_db(np.mean(side ** 2)) - _db(np.mean(mid ** 2)))
    bands, sub_share, tilt = octave_balance(stereo, sr)
    frame = int(round(0.05 * sr))
    nf = len(stereo) // frame
    frame_db = _db(np.mean(stereo[: nf * frame].reshape(nf, frame, 2) ** 2, axis=(1, 2))) if nf else np.array([-120.0])

    report = {
        "label": label,
        "integrated_lufs": integrated,
        "loudness_range_lu": loudness_range(stereo, sr, weighted),
        "max_short_term_lufs": float(np.max(short_term)),
        "max_momentary_lufs": float(np.max(momentary)),
        "true_peak_dbtp": tp,
        "sample_peak_dbfs": sample_peak,
        "plr_db": tp - integrated,
        "crest_factor_db": sample_peak - rms,
        "clip_runs": _clip_runs(stereo, QC["clip_level"], QC["clip_run_samples"]),
        "dc_offset": [float(x) for x in stereo.mean(axis=0)],
        "noise_floor_dbfs": float(np.percentile(frame_db, 5)),
        "phase_correlation_mean": corr_mean,
        "phase_correlation_p5": corr_p5,
        "side_to_mid_db": width_db,
        "mono_fold_loss_lu": integrated - mono_lufs,
        "octave_balance_db": bands,
        "sub40_share_db": sub_share,
        "spectral_tilt_db_per_octave": tilt,
    }
    if voice_mono is not None and music is not None:
        active, times, _ = speech_activity(voice_mono, sr)
        report["speech_band_masking_margin_db"] = masking_margin(voice_mono, music, sr, active, times)

    warnings = []
    if spec is not None:
        report["delivery_spec"] = asdict(spec)
        if abs(integrated - spec.integrated_lufs) > spec.tolerance_lu:
            warnings.append(f"integrated {integrated:.1f} LUFS outside {spec.name} "
                            f"{spec.integrated_lufs:.0f} +/-{spec.tolerance_lu:g}")
        if tp > spec.true_peak_dbtp + 0.05:
            warnings.append(f"true peak {tp:.2f} dBTP over {spec.true_peak_dbtp:.1f} ceiling")
        if report["plr_db"] < QC["min_plr_db"]:
            warnings.append(f"PLR {report['plr_db']:.1f} dB (over-limited)")
    if report["clip_runs"]:
        warnings.append(f"{report['clip_runs']} clipped runs")
    if max(abs(x) for x in report["dc_offset"]) > QC["dc_offset_max"]:
        warnings.append("DC offset")
    if corr_p5 < QC["min_correlation"]:
        warnings.append(f"phase correlation drops to {corr_p5:+.2f} (5th pct) (mono risk)")
    if report["mono_fold_loss_lu"] > QC["max_mono_loss_lu"]:
        warnings.append(f"mono fold-down loses {report['mono_fold_loss_lu']:.1f} LU")
    if sub_share > QC["max_sub_share_db"]:
        warnings.append(f"sub-40 Hz energy {sub_share:.1f} dB of total (wasted headroom)")
    margin = report.get("speech_band_masking_margin_db")
    if margin is not None and margin < QC["min_masking_margin_db"]:
        warnings.append(f"music masks speech band (margin {margin:.1f} dB)")
    report["warnings"] = warnings
    return report


# ============================================================
# THE MIX: voice + score -> delivery master
# ============================================================

def mix_and_master(voice_mono, music, sr, delivery=DEFAULT_DELIVERY, settings=MixSettings()):
    """Narration-led dialogue mix and master.

    Returns (master float32 (n, 2), report dict)."""
    spec = DELIVERY_SPECS[delivery] if isinstance(delivery, str) else delivery
    n = len(voice_mono)
    music = as_stereo(music)[:n]
    if len(music) < n:
        music = np.pad(music, ((0, n - len(music)), (0, 0)))

    voice = highpass(np.asarray(voice_mono, dtype=np.float64), sr, settings.voice_highpass_hz)[:, 0]
    music = highpass(music, sr, settings.music_highpass_hz)

    duck_db, speech_weight, duck_stats = dialogue_duck_curve(voice, music, sr, settings)
    carve_db = -settings.carve_depth_db * speech_weight
    bed = dynamic_presence_cut(music, sr, carve_db, settings.carve_center_hz, settings.carve_q)
    bed = bed * (10.0 ** (duck_db / 20.0))[:, None]

    voice_st = np.repeat(voice[:, None], 2, axis=1)
    mix = voice_st + bed
    master, limiter_gr = master_to_spec(mix, sr, spec, settings)

    # Everything downstream of the mix bus gain is linear except the limiter,
    # so measure the achieved DMR on the pre-master stems.
    active, times, _ = speech_activity(voice, sr)
    bed_times, bed_st = loudness_curve(bed, sr, 3.0, 0.1)
    bed_under_speech = np.interp(times[active], bed_times, bed_st) if active.any() else np.array([np.nan])
    duck_stats["achieved_dmr_lu_median"] = float(duck_stats["voice_speech_lufs"] - np.nanmedian(bed_under_speech))
    duck_stats["target_dmr_lu"] = settings.target_dmr_lu
    duck_stats["carve"] = {"center_hz": settings.carve_center_hz, "q": settings.carve_q,
                           "depth_db": settings.carve_depth_db}
    duck_stats["limiter_max_gain_reduction_db"] = limiter_gr

    master = np.ascontiguousarray(master, dtype=np.float32)
    report = {
        "settings": asdict(settings),
        "dialogue_mix": duck_stats,
        "master_qc": qc_report(master, sr, spec, voice_mono=voice, music=bed, label="master"),
    }
    return master, report


def format_qc(report):
    """Short human-readable QC lines for logs."""
    r = report
    lines = [
        f"{r['label'] or 'audio'}: {r['integrated_lufs']:.1f} LUFS  LRA {r['loudness_range_lu']:.1f} LU  "
        f"TP {r['true_peak_dbtp']:+.2f} dBTP  PLR {r['plr_db']:.1f} dB",
        f"  corr {r['phase_correlation_mean']:+.2f} (p5 {r['phase_correlation_p5']:+.2f})  "
        f"mono loss {r['mono_fold_loss_lu']:.1f} LU  tilt {r['spectral_tilt_db_per_octave'] or 0:+.1f} dB/oct",
    ]
    if r.get("speech_band_masking_margin_db") is not None:
        lines.append(f"  speech-band margin {r['speech_band_masking_margin_db']:.1f} dB")
    for w in r["warnings"]:
        lines.append(f"  WARNING: {w}")
    return lines

# ##########  pipeline.py  ##########

# ============================================================
# STORY SCORING LAB — GENERALIZATION V2 PIPELINE
#
# narration -> transcript -> mood -> 7 story sections -> fresh motif ->
# reference windows -> core/pressure/climax phrases (quality gated) ->
# V2 exact-waveform optimizer -> exact render -> adaptive ducking ->
# score_raw / score_ducked / voice_music_preview / manifest.json
#
# Kaggle: paste the built single file (dist/) into a cell, or run
#   python pipeline.py --input-root /kaggle/input --stories 71,72,86
# ============================================================

import argparse
import json
import os
import zipfile
from pathlib import Path

import numpy as np



PIPELINE_VERSION = "GENERALIZATION_V2_EXACT_WAVEFORM"

DEFAULT_INPUT_ROOTS = ["/kaggle/input"]
DEFAULT_OUT_ROOT = "/kaggle/working/story_generalization_v2_exact_waveform"
DEFAULT_TEST_STORY_IDS = ["71", "72", "86"]
DEFAULT_MAX_STORIES = 3


def _json_default(value):
    if isinstance(value, (np.floating,)):
        return float(value)
    if isinstance(value, (np.integer,)):
        return int(value)
    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, Path):
        return str(value)
    raise TypeError(f"not JSON serializable: {type(value)}")


def save_json(path, data):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, default=_json_default)


def load_voice_mono(path):
    audio, sr = read_audio(path)
    return f32(resample_mono(to_mono(audio), sr, SR))


# ============================================================
# SHARED SCORING STAGE (used by the full run AND by the offline replay)
# ============================================================

def score_story(layer_phrases, boundaries, voice_mono, story_dir, manifest_base, log=print,
                delivery=DEFAULT_DELIVERY):
    """Optimize -> exact render -> measure -> duck -> export.

    The manifest's optimizer metrics and final metrics come from the same
    render_score()/measure_score() code, then the written score_raw.wav is
    read back and measured a third time (16-bit file)."""
    story_dir = Path(story_dir)
    story_dir.mkdir(parents=True, exist_ok=True)
    voice_mono = f32(voice_mono)
    total_samples = len(voice_mono)
    boundaries = [float(x) for x in boundaries]
    phrases = normalize_layer_input(layer_phrases)

    log("\nOptimizing actual generated material (V2 exact waveform)...")
    opt = optimize_story(phrases, boundaries, total_samples=total_samples, log=log)

    log("\nBest phrase orders:")
    for name in LAYER_NAMES:
        log(f"  {name:<10}{tuple(opt['orders'][name])} phase={opt['phases_seconds'][name]:.2f}s")

    # Final exact render — fresh, from the phrases, not from optimizer caches.
    final_music = render_score(phrases, opt["orders"], opt["phases_seconds"], boundaries, total_samples)
    final_metrics = measure_score(final_music, boundaries)

    raw_path = story_dir / "score_raw.wav"
    write_audio(raw_path, final_music, SR)
    file_audio, _ = read_audio(raw_path)
    file_metrics = measure_score(fit_length(file_audio, total_samples), boundaries)

    duck_env, duck_stats = duck_envelope(voice_mono, total_samples)
    ducked = apply_ducking(final_music, duck_env)
    ducked_path = story_dir / "score_ducked.wav"
    write_audio(ducked_path, ducked, SR)

    preview = make_preview(voice_mono, ducked)
    preview_path = story_dir / "voice_music_preview.wav"
    write_audio(preview_path, preview, SR)

    # Engineered dialogue mix + delivery master (additive: the legacy
    # ducked/preview files above are unchanged).
    master, mix_report = mix_and_master(voice_mono, final_music, SR, delivery)
    master_path = story_dir / "voice_music_master.wav"
    write_audio(master_path, master, SR)
    mix_report["score_raw_qc"] = qc_report(final_music, SR, label="score_raw")
    mix_report["legacy_preview_qc"] = qc_report(
        preview, SR, DELIVERY_SPECS[delivery], label="legacy_preview")

    align = alignment_report(opt["metrics"], final_metrics)
    align_file = alignment_report(opt["metrics"], file_metrics)

    section_rows = [
        {
            "section": label,
            "start": boundaries[i],
            "end": boundaries[i + 1],
            "rms_db": final_metrics["section_db"][i],
            "target_db": float(SECTION_TARGETS_DB[i]),
            "error_db": final_metrics["section_db"][i] - float(SECTION_TARGETS_DB[i]),
        }
        for i, label in enumerate(STORY_LABELS)
    ]
    boundary_rows = [
        {
            "boundary": f"{STORY_LABELS[i - 1]} -> {STORY_LABELS[i]}",
            "time": boundaries[i],
            "jump_db": final_metrics["boundary_jumps_db"][i - 1],
        }
        for i in range(1, 7)
    ]

    manifest = dict(manifest_base)
    manifest.update({
        "optimizer_version": opt["optimizer_version"],
        "pipeline_version": PIPELINE_VERSION,
        "duration_seconds": total_samples / SR,
        "boundaries": boundaries,
        "optimizer": opt,
        "final_metrics": final_metrics,
        "final_file_metrics_pcm16": file_metrics,
        "alignment": {
            "optimizer_vs_final_render": align,
            "optimizer_vs_written_pcm16_file": align_file,
        },
        "final_story_energy": section_rows,
        "final_boundary_continuity": boundary_rows,
        "ducking": duck_stats,
        "mix_master": mix_report,
        "files": {"raw": str(raw_path), "ducked": str(ducked_path), "preview": str(preview_path),
                  "master": str(master_path)},
    })
    save_json(story_dir / "manifest.json", manifest)

    log("\nFINAL STORY RESULT")
    log(f"Duration: {total_samples / SR:.3f}s")
    log(f"Optimizer exact objective: {opt['objective']:.4f}   final objective: {final_metrics['objective']:.4f}")
    log(f"Peak gap Discovery -> Revelation: optimizer {opt['metrics']['peak_gap_db']:+.3f} dB, "
        f"final {final_metrics['peak_gap_db']:+.3f} dB")
    log("\nEnergy:")
    for row in section_rows:
        log(f"  {row['section']:<28}{row['rms_db']:8.2f} dB   (target {row['target_db']:.1f})")
    log("\nBoundaries:")
    for row in boundary_rows:
        log(f"  {row['boundary']}: {row['jump_db']:+.2f} dB")
    log(f"\nAlignment optimizer vs final: worst {align['worst_db_diff']:.6f} dB -> "
        f"{'ALIGNED' if align['aligned'] else 'MISMATCH'}")
    log(f"Alignment optimizer vs 16-bit file: worst {align_file['worst_db_diff']:.6f} dB")
    log(f"Average duck: {duck_stats['average_duck_db']:.2f} dB")
    dm = mix_report["dialogue_mix"]
    log(f"\nDialogue mix: voice {dm['voice_speech_lufs']:.1f} LUFS, DMR {dm['achieved_dmr_lu_median']:.1f} LU "
        f"(target {dm['target_dmr_lu']:.0f}), duck under speech {dm['average_duck_db_during_speech']:.1f} dB, "
        f"limiter {dm['limiter_max_gain_reduction_db']:.1f} dB")
    for line in format_qc(mix_report["master_qc"]) + format_qc(mix_report["legacy_preview_qc"]):
        log(line)
    return manifest


# ============================================================
# FULL STORY (Stable Audio generation + scoring)
# ============================================================

def process_story(story_index, story_path, out_root, run_seed, log=print):
    """run_seed: the ONE seed for this whole production job (all stories in
    the job share it). Every motif/phrase seed is derived from it, so this
    job's material differs from any other job's, while re-running this exact
    story_index with this exact run_seed reproduces it bit-for-bit."""
    story_dir = Path(out_root) / f"story_{story_index:02d}_{Path(story_path).stem}"
    story_dir.mkdir(parents=True, exist_ok=True)
    log("\n" + "=" * 80)
    log(f"STORY {story_index}: {os.path.basename(story_path)}  (run_seed={run_seed})")
    log("=" * 80)

    voice_mono = load_voice_mono(story_path)
    duration = len(voice_mono) / SR

    transcript_path = find_matching_json(story_path)
    segments = []
    if transcript_path is not None:
        try:
            segments = load_transcript_json(transcript_path)
            log(f"Transcript: {transcript_path}")
        except Exception as exc:
            log(f"Transcript JSON failed: {exc!r}")
    if not segments:
        segments = transcribe_with_whisper(story_path, log=log)
    segments = normalize_text(segments)

    mood = build_story_mood(segments)
    boundaries = infer_story_boundaries(segments, duration)
    log(f"Detected mood: {mood}")
    log("Story boundaries:")
    for i, label in enumerate(STORY_LABELS):
        log(f"  {label:<28}{boundaries[i]:7.2f}s -> {boundaries[i + 1]:7.2f}s")

    motif, motif_path, prompt, motif_seed = generate_motif(story_index, mood, story_dir, run_seed)
    references, reference_starts = choose_references(motif)
    for i, reference in enumerate(references, start=1):
        write_audio(story_dir / f"reference_{i:02d}.wav", reference, SR)
    motif_profile = chroma_profile(motif)

    layer_phrases, quality_rows = generate_layer_phrases(
        story_index, mood, references, motif_profile, story_dir, run_seed, log=log
    )

    manifest_base = {
        "story_file": str(story_path),
        "run_seed": run_seed,
        "transcript_file": transcript_path,
        "transcript_segments": len(segments),
        "detected_mood": mood,
        "motif": {
            "path": motif_path,
            "prompt": prompt,
            "seed": motif_seed,
            "reference_starts_seconds": [float(x / SR) for x in reference_starts],
        },
        "quality_report": quality_rows,
    }
    return score_story(layer_phrases, boundaries, voice_mono, story_dir, manifest_base, log=log)


# ============================================================
# SUMMARY
# ============================================================

def summarize(manifests):
    rows = []
    for index, m in enumerate(manifests, start=1):
        final = m["final_metrics"]
        opt = m["optimizer"]["metrics"]
        sims = [r.get("motif_similarity") for r in m.get("quality_report", [])
                if r.get("motif_similarity") is not None]
        valid = [r for r in m.get("quality_report", []) if r.get("valid")]
        rows.append({
            "story": index,
            "file": os.path.basename(m["story_file"]),
            "duration_sec": m["duration_seconds"],
            "optimizer_objective": m["optimizer"]["objective"],
            "final_objective": final["objective"],
            "stage1_objective": m["optimizer"]["stage1"]["objective"],
            "section_db": final["section_db"],
            "discovery_db": final["section_db"][4],
            "revelation_db": final["section_db"][5],
            "revelation_minus_discovery_db": final["peak_gap_db"],
            "optimizer_peak_gap_db": opt["peak_gap_db"],
            "aftermath_db": final["section_db"][6],
            "boundary_jumps_db": final["boundary_jumps_db"],
            "max_boundary_jump_db": final["max_abs_boundary_jump_db"],
            "optimizer_boundary_penalty": opt["boundary_penalty"],
            "final_boundary_penalty": final["boundary_penalty"],
            "local_penalty": final["local_penalty"],
            "local_valley_depth_db": final["local_valley_depth_db"],
            "alignment_worst_db_diff": m["alignment"]["optimizer_vs_final_render"]["worst_db_diff"],
            "alignment_pcm16_worst_db_diff": m["alignment"]["optimizer_vs_written_pcm16_file"]["worst_db_diff"],
            "aligned": m["alignment"]["optimizer_vs_final_render"]["aligned"],
            "motif_similarity_min": min(sims) if sims else None,
            "motif_similarity_mean": float(np.mean(sims)) if sims else None,
            "valid_phrase_reports": len(valid),
            "average_duck_db": m["ducking"]["average_duck_db"],
            "master_integrated_lufs": m["mix_master"]["master_qc"]["integrated_lufs"],
            "master_true_peak_dbtp": m["mix_master"]["master_qc"]["true_peak_dbtp"],
            "master_lra_lu": m["mix_master"]["master_qc"]["loudness_range_lu"],
            "dialogue_to_music_lu": m["mix_master"]["dialogue_mix"]["achieved_dmr_lu_median"],
            "speech_band_margin_db": m["mix_master"]["master_qc"].get("speech_band_masking_margin_db"),
            "master_warnings": m["mix_master"]["master_qc"]["warnings"],
        })
    return rows


def print_summary(rows, log=print):
    log("\n" + "=" * 80)
    log("GENERALIZATION V2 SUMMARY")
    log("=" * 80)
    for row in rows:
        log(f"\nStory {row['story']}: {row['file']}")
        log(f"  Objective (optimizer / final): {row['optimizer_objective']:.4f} / {row['final_objective']:.4f}")
        log(f"  Discovery: {row['discovery_db']:.2f} dB   Revelation: {row['revelation_db']:.2f} dB")
        log(f"  Revelation - Discovery (optimizer / final): "
            f"{row['optimizer_peak_gap_db']:+.3f} / {row['revelation_minus_discovery_db']:+.3f} dB")
        log(f"  Aftermath: {row['aftermath_db']:.2f} dB")
        log(f"  Max boundary jump: {row['max_boundary_jump_db']:.2f} dB")
        log(f"  Optimizer vs final worst diff: {row['alignment_worst_db_diff']:.6f} dB "
            f"({'ALIGNED' if row['aligned'] else 'MISMATCH'})")
        log(f"  Average duck: {row['average_duck_db']:.2f} dB")


def zip_folder(folder, zip_path):
    folder = Path(folder)
    with zipfile.ZipFile(zip_path, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        for path in folder.rglob("*"):
            if path.is_file():
                zf.write(path, arcname=path.relative_to(folder))
    return zip_path


# ============================================================
# MAIN
# ============================================================

def main(argv=None):
    parser = argparse.ArgumentParser(description="Story Scoring Lab — Generalization V2")
    parser.add_argument("--input-root", action="append", default=None,
                        help="Folder(s) searched recursively for narration audio.")
    parser.add_argument("--out-root", default=DEFAULT_OUT_ROOT)
    parser.add_argument("--stories", default=",".join(DEFAULT_TEST_STORY_IDS),
                        help="Comma-separated story ids; empty string = first 3 eligible.")
    parser.add_argument("--max-stories", type=int, default=DEFAULT_MAX_STORIES)
    parser.add_argument("--no-zip", action="store_true")
    parser.add_argument("--run-seed", type=int, default=None,
                        help="Seed for this whole job (all stories in it). Omit for a fresh "
                             "production job (default); pass an explicit value to reproduce "
                             "a previous job's exact motif/phrases.")
    # parse_known_args: Kaggle/Jupyter pass their own -f argument.
    args, _ = parser.parse_known_args(argv)

    input_roots = args.input_root or DEFAULT_INPUT_ROOTS
    story_ids = [s.strip() for s in args.stories.split(",") if s.strip()]
    out_root = Path(args.out_root)
    out_root.mkdir(parents=True, exist_ok=True)

    run_seed = args.run_seed if args.run_seed is not None else generate_run_seed()
    print(f"\nRun seed for this job: {run_seed}"
          f"{' (explicit)' if args.run_seed is not None else ' (fresh — record this to reproduce this job)'}")

    story_files = discover_stories(input_roots, story_ids, args.max_stories)
    print("\nSelected stories:")
    for i, path in enumerate(story_files, start=1):
        print(f"{i}. {os.path.basename(path)}")

    manifests = [process_story(i, path, out_root, run_seed) for i, path in enumerate(story_files, start=1)]

    rows = summarize(manifests)
    for row, m in zip(rows, manifests):
        row["run_seed"] = run_seed
    save_json(out_root / "generalization_summary.json", rows)
    print_summary(rows)

    if not args.no_zip:
        zip_path = out_root.parent / f"{out_root.name}.zip"
        zip_folder(out_root, zip_path)
        print(f"ZIP: {zip_path}")

    print("\n" + "=" * 80)
    print("GENERALIZATION V2 COMPLETE — EXACT WAVEFORM OPTIMIZER")
    print("=" * 80)
    print(f"Summary: {out_root / 'generalization_summary.json'}")
    return rows


if __name__ == "__main__":
    main()
